 ["orbits","\"$HORIZON_BIN\" search --name OrbitsInAffineOpen -n 100 --json 2>/dev/null | jq -r '.[] | select(.library==\"Algebraic-Jacobian-Challenge\" or .library==\"Algebraic-Jacobian-Challenge-Rebuild\") | [.library,.kind,.name,.signature,.file,(.line|tostring)] | @tsv'"],
