];
const out=await Promise.all(cmds.map(async ([n,cmd])=>{
 const r=await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",yield_time_ms:30000,max_output_tokens:30000});
 return `### ${n}\n${r.output}`;
}));
out.forEach(text);

const qs=[
 "finite-stage glued Pic0 representative",
 "Pic0FiniteStageGlued projective",
 "Pic0 finite stage glued finite affine",
 "Pic0 representer projectivity",
 "finite stage Pic0 action semilinear"
];
for (const q of qs) {
 const r=await tools.exec_command({cmd:`"$HORIZON_BIN" search "${q}" -n 30 --json 2>/dev/null | jq -r '.[] | select(.library==\"Algebraic-Jacobian-Challenge-Rebuild\" or .library==\"Algebraic-Jacobian-Challenge\") | [.library,.kind,.name,.signature,.file,(.line|tostring)] | @tsv'`,workdir:'/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild',yield_time_ms:30000,max_output_tokens:30000});
 text(`### ${q}\n${r.output}`);
}

const cmds=[
 ["glued-over-uses","rg -n '\\.gluedOver|gluedOver|glueData\\.glued|FiniteInAffine|IsProjective|IsHQuasiProjective|OrbitsInAffineOpen|SemilinearGalAction' AlgebraicJacobian/Picard/Pic0FiniteStage*.lean AlgebraicJacobian/Picard/Pic0Galois*.lean AlgebraicJacobian/Picard/Pic0FiniteGalois*.lean", "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"],
 ["planned-files","find AlgebraicJacobian/Picard -maxdepth 1 -type f \\( -name 'Pic0FiniteStageOrbitAffine.lean' -o -name 'Pic0FiniteStageStableAffine*.lean' \\) -print", "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"],
